def completed_dates(apps, schema_editor):
    """Los juegos que ya estaban en «Completado» toman como fecha en que se terminaron la de la última vez que su dueño
    los pasó a ese estado (su actividad) o, si no la hay, el «terminado el» de su última reseña. Sin ninguna se quedan
    sin fecha: cuentan en los retos que no tienen fecha de inicio."""
    LibraryEntry = apps.get_model("library", "LibraryEntry")
    Review = apps.get_model("library", "Review")
    Activity = apps.get_model("social", "Activity")
    for entry in LibraryEntry.objects.filter(status="completed", completed_at__isnull=True):
        moment = (
            Activity.objects.filter(user_id=entry.user_id, game_id=entry.game_id, kind="game", status="completed")
            .order_by("-updated_at").values_list("updated_at", flat=True).first()
        )
        if moment is None:
            finished = (
                Review.objects.filter(user_id=entry.user_id, game_id=entry.game_id, finished_on__isnull=False)
                .order_by("-finished_on").values_list("finished_on", flat=True).first()
            )
            if finished:
                moment = timezone.make_aware(datetime.combine(finished, time(12)))
        if moment is not None:
            entry.completed_at = moment
            entry.save(update_fields=["completed_at"])


